/**
 * Differential certification (FORGE-087; PAR-172/176). Runs every scenario on
 * each locally available profile and compares the normalized per-step results
 * pairwise. A difference is *explained* only when it sits under a key that is
 * provider-generated by contract (cursor tokens, provider-signed URLs, cache
 * timestamps); everything else is unexplained drift and fails certification.
 * Every profile that could not run is listed with the reason, so the manifest
 * can never say "all profiles passed" when one was skipped.
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import type { AppBundle } from "@forge/runtime";
import { runScenario, type Report } from "./runner.js";
import { loadScenarios } from "./scenarios.js";
import type { Target } from "./target.js";

/**
 * Keys whose values are legitimately provider-generated or provider-physical; differences under them are
 * explained, never hidden: opaque cursors, cache timestamps, object generations, the caller's requestId, and the
 * atomic budget's *physical* action count (D1 statements vs DynamoDB transaction items vs Postgres statements;
 * the logical change count must still agree).
 */
export const EXPLAINED_KEYS = new Set(["next", "cursor", "freshUntil", "loadedAt", "generation", "lastEventAt", "at", "startedAt", "endedAt", "requestId", "physicalActions", "physicalLimit"]);

export interface Difference { scenario: string; step: string; path: string; a: unknown; b: unknown; explained: boolean; key?: string }
export interface DifferentialReport {
  version: "differential/1";
  at: string;
  profiles: { name: string; ran: boolean; reason?: string; scenarios: number; failures: number }[];
  pairs: { a: string; b: string; compared: number; explained: number; unexplained: number }[];
  differences: Difference[];
  drift: "none" | "unexplained";
}

function walk(a: unknown, b: unknown, path: string, key: string | undefined, out: Omit<Difference, "scenario" | "step">[]): void {
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return void out.push({ path, a: a.length, b: b.length, explained: key !== undefined && EXPLAINED_KEYS.has(key), ...(key ? { key } : {}) });
    a.forEach((x, i) => walk(x, b[i], `${path}[${i}]`, key, out));
    return;
  }
  if (a && b && typeof a === "object" && typeof b === "object") {
    const keys = new Set([...Object.keys(a as object), ...Object.keys(b as object)]);
    for (const k of keys) walk((a as Record<string, unknown>)[k], (b as Record<string, unknown>)[k], path ? `${path}.${k}` : k, k, out);
    return;
  }
  if (a !== b) out.push({ path, a, b, explained: key !== undefined && EXPLAINED_KEYS.has(key), ...(key ? { key } : {}) });
}

/**
 * Compare two runs step by step. From a scenario's first `race` step onward, outcomes are legitimately
 * nondeterministic (which racer wins is not contract; the scenario's own invariant checks are), so those
 * steps are compared for *shape* only and any value difference is explained as `race`.
 */
export function compareReports(a: Report[], b: Report[], raceSteps: Record<string, string[]> = {}): Difference[] {
  const out: Difference[] = [];
  for (const ra of a) {
    const rb = b.find((r) => r.scenario === ra.scenario);
    if (!rb) { out.push({ scenario: ra.scenario, step: "*", path: "", a: "present", b: "absent", explained: false }); continue; }
    const races = raceSteps[ra.scenario] ?? [];
    let afterRace = false;
    for (const step of Object.keys(ra.results)) {
      if (races.includes(step)) afterRace = true;
      const diffs: Omit<Difference, "scenario" | "step">[] = [];
      walk(ra.results[step], rb.results[step], "", undefined, diffs);
      for (const d of diffs) out.push({ scenario: ra.scenario, step, ...(afterRace ? { ...d, explained: true, key: "race" } : d) });
    }
  }
  return out;
}

export async function runDifferential(targets: { name: string; target: Target | null; reason?: string }[], bundle?: AppBundle): Promise<DifferentialReport> {
  const scenarios = loadScenarios();
  const runs = new Map<string, Report[]>();
  const profiles: DifferentialReport["profiles"] = [];
  for (const t of targets) {
    if (!t.target) { profiles.push({ name: t.name, ran: false, reason: t.reason ?? "unavailable", scenarios: 0, failures: 0 }); continue; }
    const reports: Report[] = [];
    for (const s of scenarios) reports.push(await runScenario(s, t.target, { tenant: `diff-${t.name}-${s.id}` }));
    runs.set(t.name, reports);
    profiles.push({ name: t.name, ran: true, scenarios: reports.length, failures: reports.reduce((n, r) => n + r.failures.length, 0) });
  }
  const names = [...runs.keys()];
  const pairs: DifferentialReport["pairs"] = [];
  const differences: Difference[] = [];
  const raceSteps: Record<string, string[]> = Object.fromEntries(scenarios.map((s) => [s.id, s.steps.filter((st) => "race" in st).map((st) => st.name)]));
  for (let i = 0; i < names.length; i++) for (let j = i + 1; j < names.length; j++) {
    const d = compareReports(runs.get(names[i]!)!, runs.get(names[j]!)!, raceSteps);
    pairs.push({ a: names[i]!, b: names[j]!, compared: runs.get(names[i]!)!.reduce((n, r) => n + Object.keys(r.results).length, 0), explained: d.filter((x) => x.explained).length, unexplained: d.filter((x) => !x.explained).length });
    differences.push(...d);
  }
  void bundle;
  return { version: "differential/1", at: new Date().toISOString(), profiles, pairs, differences, drift: differences.some((d) => !d.explained) || profiles.some((p) => p.ran && p.failures > 0) ? "unexplained" : "none" };
}

